// The built-in stretch library. Exercise data by RepDB (https://repdb.co):
// the stretches of its free edition (https://github.com/RepDB/exercise-dataset)
// minus the flowing drills and rest poses, plus its deep squat hold. The
// license lets apps use it with a visible credit (see Settings) but not
// republish it as a dataset. The illustrations live in
// climbing-tracker/stretches/, held position first in `photos`.
//
// The wrist stretches at the end were written for this app and have no
// picture; the user can upload one.
//
// Adding a stretch from the library copies it into the user's exercises
// (see stretchExerciseFromLibrary), so editing it never changes this list.
// Kept free of React so the MCP server can use it too.

export const DEFAULT_HOLD_SEC = 30;

export const LIBRARY_CREDIT = { text: "Exercise data by RepDB", url: "https://repdb.co" };

export const STRETCH_LIBRARY = [
  { id: "kneeling-wrist-stretch", name: "Kneeling Wrist Stretch", muscles: ["forearm flexors"], twoSided: false, equipment: null, photos: ["kneeling-wrist-stretch-main.webp"],
    instructions: "1. Kneel on all fours and place your palms flat on the floor.\n2. Turn your hands so the fingers point back toward your knees.\n3. Keep your palms down and rock your weight back gently.\n4. Hold for 20 to 30 seconds, breathing steadily.\n\n• Keep your palms flat as you lean back.\n• Stretch to mild tension, never to pain." },
  { id: "cow-face-pose", name: "Cow Face Pose", muscles: ["gluteus maximus", "gluteus medius", "posterior deltoid", "triceps brachii"], twoSided: true, equipment: null, photos: ["cow-face-pose-main.webp"],
    instructions: "1. Sit on the floor and cross one knee directly over the other so the knees stack in the midline.\n2. Walk the feet out towards the hips and settle both sit bones evenly on the floor.\n3. Reach the arm on the top-knee side up and bend it behind the head, then reach the other arm up the back to clasp.\n4. Hold the position for the prescribed time, keeping the chest open and the spine tall.\n5. Release and repeat with the other leg and arm on top.\n\n• Sit on a folded blanket if one sit bone lifts off the floor.\n• Hold a strap between the hands when the fingers do not meet; forcing the clasp rounds the back.\n• Keep the top elbow pointing up rather than letting it drift out to the side." },
  { id: "cross-body-shoulder-stretch", name: "Cross-Body Shoulder Stretch", muscles: ["posterior deltoid", "rhomboids"], twoSided: true, equipment: null, photos: ["cross-body-shoulder-stretch-main.webp"],
    instructions: "1. Stand tall and bring one straight arm across your chest.\n2. Hook your other forearm under it.\n3. Gently pull the arm closer to your chest.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Keep the stretching shoulder down, not shrugged.\n• Do not pull on the elbow joint itself." },
  { id: "puppy-pose", name: "Puppy Pose", muscles: ["latissimus dorsi", "posterior deltoid", "erector spinae", "trapezius"], twoSided: false, equipment: null, photos: ["puppy-pose-main.webp"],
    instructions: "1. Kneel on all fours with the hips over the knees and the hands under the shoulders.\n2. Walk the hands forward and lower the chest towards the floor, keeping the hips high.\n3. Rest the forehead or the chin on the mat and let the armpits soften downwards.\n4. Hold the position for the prescribed time, breathing into the upper back.\n5. Walk the hands back and sit onto the heels to come out.\n\n• Keep the hips stacked over the knees; sitting back turns this into child's pose.\n• Press the palms down and lift the elbows off the floor to keep the arms working.\n• Rest the forehead on a block if the chest does not reach comfortably." },
  { id: "banded-rear-delt-stretch", name: "Banded Rear Delt Stretch", muscles: ["posterior deltoid", "rhomboids", "trapezius"], twoSided: true, equipment: "resistance band", photos: ["banded-rear-delt-stretch-main.webp"],
    instructions: "1. Loop a band around one arm and hold the other end.\n2. Draw that arm horizontally across your chest.\n3. Use the band to deepen the pull gently.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Keep the working shoulder relaxed and down.\n• Relax and keep breathing throughout." },
  { id: "banded-shoulder-stretch", name: "Banded Shoulder Stretch", muscles: ["anterior deltoid", "pectoralis major"], twoSided: false, equipment: "resistance band", photos: ["banded-shoulder-stretch-main.webp"],
    instructions: "1. Hold a band behind your back, one hand high and one low.\n2. Keep light tension in the band.\n3. Open your chest and draw your shoulders gently back.\n4. Hold for 20 to 30 seconds, breathing steadily.\n\n• Keep your ribs down and avoid arching your back.\n• Move your hands farther apart to ease the stretch." },
  { id: "overhead-triceps-stretch", name: "Overhead Triceps Stretch", muscles: ["triceps brachii", "latissimus dorsi"], twoSided: true, equipment: null, photos: ["overhead-triceps-stretch-main.webp"],
    instructions: "1. Raise one arm overhead and bend the elbow.\n2. Let your hand drop down behind your head.\n3. Use the other hand to press the bent elbow back.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Keep your head upright, do not push it forward.\n• Relax and keep breathing throughout." },
  { id: "banded-triceps-stretch", name: "Banded Triceps Stretch", muscles: ["triceps brachii", "latissimus dorsi"], twoSided: true, equipment: "resistance band", photos: ["banded-triceps-stretch-main.webp"],
    instructions: "1. Hold a band that runs down your back, top hand behind your head.\n2. Anchor the lower hand at your lower back.\n3. Reach the top hand down to feel the triceps lengthen.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Keep your head upright and ribs down.\n• Relax and keep breathing throughout." },
  { id: "doorway-chest-stretch", name: "Doorway Chest Stretch", muscles: ["pectoralis major", "anterior deltoid"], twoSided: false, equipment: null, photos: ["doorway-chest-stretch-main.webp"],
    instructions: "1. Stand tall and raise your arms into a goalpost position.\n2. Bend your elbows ninety degrees, forearms vertical.\n3. Draw your elbows back and squeeze your shoulder blades.\n4. Hold for 20 to 30 seconds, breathing steadily.\n\n• Keep your ribs down and avoid arching your back.\n• Stretch to mild tension, never to pain." },
  { id: "fish-pose", name: "Fish Pose", muscles: ["erector spinae", "pectoralis major", "anterior deltoid", "hip flexors"], twoSided: false, equipment: null, photos: ["fish-pose-main.webp"],
    instructions: "1. Lie on your back with the legs straight and the arms alongside the body, palms down under the hips.\n2. Press the forearms into the floor and lift the chest towards the ceiling.\n3. Let the crown of the head rest lightly on the floor without putting weight through the neck.\n4. Hold the position for the prescribed time, breathing into the upper chest.\n5. Lift the head, then lower the back down.\n\n• Carry the weight in the forearms, not the head; the neck only guides the position.\n• Place a block lengthwise under the upper back if the floor version pinches.\n• Keep the legs active and the thighs rolling slightly inwards." },
  { id: "banded-chest-stretch", name: "Banded Chest Stretch", muscles: ["pectoralis major", "anterior deltoid"], twoSided: false, equipment: "resistance band", photos: ["banded-chest-stretch-main.webp"],
    instructions: "1. Hold a band behind your back with both hands.\n2. Straighten your arms and draw them apart.\n3. Lift your chest and squeeze your shoulder blades.\n4. Hold for 20 to 30 seconds, breathing steadily.\n\n• Keep your shoulders down away from your ears.\n• Stretch to mild tension, never to pain." },
  { id: "bench-chest-stretch", name: "Bench Chest Stretch", muscles: ["pectoralis major", "anterior deltoid"], twoSided: false, equipment: "flat bench", photos: ["bench-chest-stretch-main.webp"],
    instructions: "1. Kneel with your back to a bench.\n2. Place both hands behind you on the edge of the bench.\n3. Sink your hips down to open the chest.\n4. Hold for 20 to 30 seconds, breathing steadily.\n\n• Keep your shoulders down away from your ears.\n• Stretch to mild tension, never to pain." },
  { id: "cat-stretch", name: "Cat Stretch", muscles: ["erector spinae", "rhomboids", "trapezius"], twoSided: false, equipment: null, photos: ["cat-stretch-main.webp"],
    instructions: "1. Start on all fours, hands under shoulders and knees under hips.\n2. Round your spine up toward the ceiling.\n3. Tuck your chin toward your chest.\n4. Hold for 20 to 30 seconds, breathing steadily.\n\n• Push the floor away with your hands to spread the shoulder blades.\n• Relax and keep breathing throughout." },
  { id: "childs-pose", name: "Child's Pose", muscles: ["erector spinae", "latissimus dorsi", "trapezius"], twoSided: false, equipment: null, photos: ["childs-pose-main.webp"],
    instructions: "1. Kneel and sit your hips back toward your heels.\n2. Fold your torso forward over your thighs.\n3. Reach both arms out long on the floor in front.\n4. Hold for 20 to 30 seconds, breathing steadily.\n\n• Spread your knees wider to rest your chest lower.\n• Relax and keep breathing throughout." },
  { id: "neck-side-stretch", name: "Neck Side Stretch", muscles: ["trapezius"], twoSided: true, equipment: null, photos: ["neck-side-stretch-main.webp"],
    instructions: "1. Sit or stand tall with your shoulders relaxed.\n2. Tilt your head so one ear drops toward that shoulder.\n3. Rest that hand lightly over your head for gentle weight.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Let the weight of your hand do the work — do not pull hard.\n• Keep the opposite shoulder pressed down." },
  { id: "plow-pose", name: "Plow Pose", muscles: ["erector spinae", "hamstrings", "gluteus maximus", "trapezius"], twoSided: false, equipment: null, photos: ["plow-pose-main.webp"],
    instructions: "1. Lie on your back with the arms alongside the body, palms down.\n2. Lift both legs overhead and support the lower back with the hands.\n3. Lower the toes towards the floor behind the head, keeping the legs as straight as comfort allows.\n4. Hold the position for the prescribed time, breathing steadily and keeping the head still.\n5. Roll down one vertebra at a time with the hands supporting the back.\n\n• Never turn the head while you are in the pose; the neck is loaded and must stay neutral.\n• Rest the toes on a chair or a stack of cushions if the floor is out of reach.\n• Skip this pose entirely if you have any neck complaints." },
  { id: "seated-spinal-twist", name: "Seated Spinal Twist", muscles: ["erector spinae", "obliques", "gluteus maximus"], twoSided: true, equipment: null, photos: ["seated-spinal-twist-main.webp"],
    instructions: "1. Sit with one leg straight and cross the other foot over it.\n2. Brace the opposite elbow against the outside of the bent knee.\n3. Rotate your torso toward the bent knee and look over your shoulder.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Sit tall and lengthen your spine before twisting.\n• Twist from the mid-back, not the lower back." },
  { id: "supine-spinal-twist", name: "Supine Spinal Twist", muscles: ["erector spinae", "obliques", "gluteus maximus"], twoSided: true, equipment: null, photos: ["supine-spinal-twist-main.webp"],
    instructions: "1. Lie on your back and bend one knee toward your chest.\n2. Guide that knee across your body toward the floor.\n3. Stretch your arms out wide and turn your head away.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Keep both shoulders on the floor.\n• Relax and keep breathing throughout." },
  { id: "thread-the-needle", name: "Thread the Needle", muscles: ["posterior deltoid", "trapezius", "erector spinae", "obliques"], twoSided: true, equipment: null, photos: ["thread-the-needle-main.webp"],
    instructions: "1. Start on all fours with the hands under the shoulders and the knees under the hips.\n2. Slide one arm underneath the body, palm facing up, until the shoulder and the side of the head rest on the mat.\n3. Keep the hips stacked over the knees and walk the top hand forward or wrap it behind the back.\n4. Hold the twist for the prescribed time, breathing into the upper back.\n5. Press the top hand into the floor to come up and repeat on the other side.\n\n• Keep the hips high over the knees; dropping them turns the rotation into a side bend.\n• Rest the head on a block if the shoulder cannot reach the floor comfortably.\n• Let the shoulder settle with the breath instead of pushing the twist deeper by force." },
  { id: "banded-lat-stretch", name: "Banded Lat Stretch", muscles: ["latissimus dorsi", "posterior deltoid"], twoSided: false, equipment: "resistance band", photos: ["banded-lat-stretch-main.webp"],
    instructions: "1. Hold a band overhead with both hands under light tension.\n2. Hinge forward at the hips with your arms reaching ahead.\n3. Let your chest sink to lengthen the sides of your back.\n4. Hold for 20 to 30 seconds, breathing steadily.\n\n• Keep your arms straight and shoulders relaxed.\n• Relax and keep breathing throughout." },
  { id: "bench-childs-pose", name: "Bench Child's Pose", muscles: ["erector spinae", "latissimus dorsi"], twoSided: false, equipment: "flat bench", photos: ["bench-childs-pose-main.webp"],
    instructions: "1. Kneel on the floor in front of a bench.\n2. Extend both arms forward and rest them on the bench.\n3. Sit your hips back toward your heels and let the chest sink.\n4. Hold for 20 to 30 seconds, breathing steadily.\n\n• Keep your arms straight and relax your neck.\n• Relax and keep breathing throughout." },
  { id: "bench-lat-stretch", name: "Bench Lat Stretch", muscles: ["latissimus dorsi", "posterior deltoid"], twoSided: false, equipment: "flat bench", photos: ["bench-lat-stretch-main.webp"],
    instructions: "1. Kneel on the floor in front of a bench.\n2. Place both hands on top of the bench.\n3. Sit your hips back and let your chest sink down.\n4. Hold for 20 to 30 seconds, breathing steadily.\n\n• Keep your arms straight and head between your arms.\n• Relax and keep breathing throughout." },
  { id: "camel-pose", name: "Camel Pose", muscles: ["erector spinae", "hip flexors", "pectoralis major", "quadriceps"], twoSided: false, equipment: null, photos: ["camel-pose-main.webp"],
    instructions: "1. Kneel with the knees hip-width apart and the hips stacked over the knees.\n2. Place the hands on the back of the pelvis with the fingers pointing down and lift the chest.\n3. Press the hips forward and arch back, reaching for the heels if the position stays comfortable.\n4. Hold the pose for the prescribed time, keeping the neck in line with the spine.\n5. Bring the hands back to the pelvis and come up chest-first.\n\n• Keep the hips over the knees; letting them travel back turns the pose into a collapse.\n• Tuck the toes under and rest the hands on raised heels if the full reach is too deep.\n• Come out slowly: lifting the head first is what usually makes people dizzy." },
  { id: "cobra-stretch", name: "Cobra Stretch", muscles: ["rectus abdominis", "hip flexors", "transverse abdominis"], twoSided: false, equipment: null, photos: ["cobra-stretch-main.webp"],
    instructions: "1. Lie face down with your hands under your shoulders.\n2. Press through your hands to lift your chest off the floor.\n3. Keep your hips and legs on the floor, shoulders relaxed.\n4. Hold for 20 to 30 seconds, breathing steadily.\n\n• Keep your elbows slightly bent — do not force full extension.\n• Draw your shoulders down away from your ears." },
  { id: "sphinx-pose", name: "Sphinx Pose", muscles: ["erector spinae", "hip flexors", "pectoralis major"], twoSided: false, equipment: null, photos: ["sphinx-pose-main.webp"],
    instructions: "1. Lie face down and place the forearms on the floor with the elbows directly under the shoulders.\n2. Press the forearms and the tops of the feet down and lift the chest.\n3. Draw the shoulders away from the ears and lengthen the back of the neck.\n4. Hold the position for the prescribed time, breathing into the front of the chest.\n5. Lower the chest to the floor and rest.\n\n• Slide the elbows slightly forward for a gentler bend, back for a deeper one.\n• Keep the glutes soft so the lower back does not clench.\n• Stop where the position feels like a stretch, not like a pinch." },
  { id: "standing-side-bend", name: "Standing Side Bend", muscles: ["obliques", "latissimus dorsi", "quadratus lumborum"], twoSided: true, equipment: null, photos: ["standing-side-bend-main.webp"],
    instructions: "1. Stand with feet hip-width and reach both arms overhead.\n2. Clasp your hands and lengthen up tall.\n3. Bend smoothly to one side in a long curve.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Keep both feet planted and hips steady.\n• Reach up and over rather than just leaning down." },
  { id: "upward-dog", name: "Upward-Facing Dog", muscles: ["erector spinae", "triceps brachii", "gluteus maximus", "pectoralis major"], twoSided: false, equipment: null, photos: ["upward-dog-main.webp"],
    instructions: "1. Lie face down with the hands beside the lower ribs and the tops of the feet on the floor.\n2. Press the hands down and straighten the arms, lifting the chest and then the thighs off the mat.\n3. Draw the shoulders back and down and keep the neck long.\n4. Hold the position for the prescribed time with only the hands and the tops of the feet on the floor.\n5. Bend the arms and lower down under control.\n\n• Keep the shoulders over the wrists rather than behind them.\n• Press the tops of the feet down; that is what lifts the thighs.\n• If the thighs cannot lift, stay in cobra instead of forcing the position." },
  { id: "downward-dog", name: "Downward-Facing Dog", muscles: ["gastrocnemius", "hamstrings", "erector spinae", "gluteus maximus", "latissimus dorsi"], twoSided: false, equipment: null, photos: ["downward-dog-main.webp"],
    instructions: "1. Start on all fours with hands slightly ahead of your shoulders.\n2. Tuck your toes and lift your hips up and back.\n3. Straighten your legs and press your heels toward the floor.\n4. Hold for 20 to 30 seconds, breathing steadily.\n\n• Bend your knees if your lower back rounds.\n• Press the floor away to lengthen your spine." },
  { id: "worlds-greatest-stretch", name: "World's Greatest Stretch", muscles: ["hamstrings", "hip flexors", "adductors", "gluteus maximus", "obliques"], twoSided: true, equipment: null, photos: ["worlds-greatest-stretch-peak.webp", "worlds-greatest-stretch-start.webp"],
    instructions: "1. Start in a push-up position with your hands under your shoulders and your body in a straight line.\n2. Step one foot forward, outside the same-side hand, into a deep lunge and keep the back leg straight.\n3. Keep the hand on the back-leg side planted under your shoulder and sink your hips toward the floor.\n4. Rotate your chest toward the front leg, lifting the arm on that side up until it points at the ceiling, and follow your hand with your eyes.\n5. Hold the open position for a breath, then lower your hand back to the floor.\n6. Step back to the push-up position and repeat on the other side, alternating sides for the planned repetitions.\n\n• Keep the back knee off the floor and the back leg active so the stretch runs through the front of the hip.\n• Rotate from the upper back rather than leaning sideways; the hips stay square and low throughout.\n• Move slowly and breathe out as you rotate; the stretch should feel open and controlled, never forced." },
  { id: "90-90-hold", name: "90/90 Hold", muscles: ["hip flexors", "gluteus maximus", "gluteus medius"], twoSided: true, equipment: null, photos: ["90-90-hold-main.webp"],
    instructions: "1. Sit on the floor and bend your front leg in front of you so your shin runs across your body and your knee is bent to about 90 degrees.\n2. Place your back leg out to the side with that knee also bent to about 90 degrees, shin pointing back.\n3. Put your hands on the floor beside your hips for support.\n4. Sit up tall, with your chest lifted and both sitting bones as close to the floor as you can manage.\n5. Hold the position, breathing slowly, feeling the stretch in the outer hip of the front leg and the front of the hip of the back leg.\n6. Hold for the planned time, then switch the legs and hold on the other side.\n\n• Keep the trunk upright; slumping takes the stretch out of the hips.\n• If the hips are tight, keep more weight on your hands or sit on a folded towel until you can sit taller.\n• Ease into the stretch and do not force the knees down; the position should feel strong, not painful." },
  { id: "butterfly-stretch", name: "Butterfly Stretch", muscles: ["adductors", "hip flexors"], twoSided: false, equipment: null, photos: ["butterfly-stretch-main.webp"],
    instructions: "1. Sit tall and press the soles of your feet together.\n2. Let your knees drop out toward the floor.\n3. Hold your feet and sit up tall.\n4. Hold for 20 to 30 seconds, breathing steadily.\n\n• Gently press the knees down with your elbows for more stretch.\n• Bring your heels closer to your body to increase intensity." },
  { id: "deep-squat-hold", name: "Deep Squat Hold", muscles: ["gluteus maximus", "quadriceps", "adductors", "erector spinae", "hamstrings", "soleus"], twoSided: false, equipment: null, photos: ["deep-squat-hold-main.webp"],
    instructions: "1. Stand with the feet slightly wider than the shoulders and the toes turned out.\n2. Clasp the hands in front of the chest and sit the hips down between the heels.\n3. Lower until the hips are below the knees while the heels stay flat on the floor.\n4. Keep the chest up and press the elbows against the knees to push them out.\n5. Hold the position, breathing steadily, then stand up.\n\n• Keep the heels flat; if they lift, place a small plate or wedge under them.\n• Push the knees out in line with the toes and keep the spine long.\n• Build the hold time gradually, standing to reset between sets." },
  { id: "frog-stretch", name: "Frog Stretch", muscles: ["adductors", "gluteus maximus", "hip flexors"], twoSided: false, equipment: null, photos: ["frog-stretch-main.webp"],
    instructions: "1. Start on your hands and knees on the floor, with your wrists under your shoulders.\n2. Slide your knees out to the sides as far as is comfortable and turn your feet out, keeping your shins in line with your knees.\n3. Lower onto your forearms and keep your back straight, not rounded.\n4. Rock your hips back toward your heels until you feel a strong stretch along your inner thighs.\n5. Hold the position and breathe slowly, keeping your hips level.\n6. Come out by sliding the knees together and sitting back before you stand.\n\n• Put a folded towel or mat under your knees if the floor is hard.\n• Go only as wide as you can keep your hips level; letting the pelvis tilt takes the stretch out of the inner thighs.\n• Rock back slowly and ease out of the position if you feel any pinching at the front of the hips." },
  { id: "garland-pose", name: "Garland Pose", muscles: ["adductors", "gluteus maximus", "quadriceps", "soleus"], twoSided: false, equipment: null, photos: ["garland-pose-main.webp"],
    instructions: "1. Stand with the feet a little wider than the hips and the toes turned slightly out.\n2. Squat down as low as the ankles allow, keeping the heels on the floor.\n3. Bring the palms together at the chest and press the elbows against the inner knees.\n4. Hold the position for the prescribed time with the chest lifted and the spine long.\n5. Press through the feet to stand back up.\n\n• Roll a towel under the heels if they lift; forcing them down rounds the lower back instead.\n• Widen the stance to make room for the pelvis rather than squeezing into a narrow squat.\n• Press the knees and elbows against each other lightly to keep the chest from collapsing." },
  { id: "happy-baby", name: "Happy Baby Pose", muscles: ["adductors", "gluteus maximus", "erector spinae", "hamstrings"], twoSided: false, equipment: null, photos: ["happy-baby-main.webp"],
    instructions: "1. Lie on your back and draw both knees towards the chest.\n2. Take hold of the outside edges of the feet, or the shins if the feet are out of reach.\n3. Open the knees wider than the ribs and stack the ankles above the knees, soles facing up.\n4. Press the feet gently into the hands and hold for the prescribed time with the lower back on the floor.\n5. Release the feet and lower the legs.\n\n• Keep the tailbone heavy on the floor rather than rolling onto the upper back.\n• Hold the shins or use a strap around the feet if the grip forces the shoulders off the mat.\n• Rock gently side to side to massage the lower back if it feels tight." },
  { id: "head-to-knee-pose", name: "Head-to-Knee Pose", muscles: ["erector spinae", "hamstrings", "adductors", "gluteus maximus"], twoSided: true, equipment: null, photos: ["head-to-knee-pose-main.webp"],
    instructions: "1. Sit with one leg straight in front of you and the other knee bent out to the side, that foot at the inner thigh.\n2. Turn the chest towards the straight leg so the navel lines up with the thigh.\n3. Hinge from the hips and reach forward along the straight leg with a long spine.\n4. Hold the fold for the prescribed time, breathing into the back of the leg.\n5. Come up with a flat back and repeat on the other side.\n\n• Sit on a folded blanket so the pelvis can tip forward instead of the back rounding.\n• Keep the toes of the straight leg pointing up rather than rolling out.\n• Use a strap around the foot when the hands do not reach it comfortably." },
  { id: "hero-pose", name: "Hero Pose", muscles: ["quadriceps", "erector spinae", "hip flexors"], twoSided: false, equipment: null, photos: ["hero-pose-main.webp"],
    instructions: "1. Kneel with the knees together and the feet slightly wider than the hips, tops of the feet flat.\n2. Sit the hips back and down between the heels, using a block or cushion if the floor is out of reach.\n3. Stack the ribs over the pelvis and rest the hands on the thighs.\n4. Hold the seat for the prescribed time, keeping the weight even on both sit bones.\n5. Come out by pressing into the hands and straightening one leg at a time.\n\n• Sit on a block whenever the knees complain; the height is a normal part of the pose.\n• Roll a towel under the ankles if the front of them feels strained.\n• Keep the feet pointing straight back rather than flaring out to the sides." },
  { id: "knee-to-chest-stretch", name: "Knee-to-Chest Stretch", muscles: ["gluteus maximus", "erector spinae"], twoSided: true, equipment: null, photos: ["knee-to-chest-stretch-main.webp"],
    instructions: "1. Lie on your back with both legs straight.\n2. Pull one knee in and hug it to your chest with both hands.\n3. Keep the other leg relaxed on the floor.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Keep your head and shoulders relaxed on the floor.\n• Relax and keep breathing throughout." },
  { id: "kneeling-hip-flexor-stretch", name: "Kneeling Hip Flexor Stretch", muscles: ["hip flexors", "adductors", "quadriceps"], twoSided: true, equipment: null, photos: ["kneeling-hip-flexor-stretch-main.webp"],
    instructions: "1. Kneel on one knee with the other foot flat in front.\n2. Keep your torso upright and core gently braced.\n3. Press your hips forward until the front of the rear hip stretches.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Squeeze the glute of the kneeling leg to protect the lower back.\n• Avoid arching your lower back." },
  { id: "lean-back-90-90-hold", name: "Lean-Back 90/90 Hold", muscles: ["hip flexors", "gluteus maximus", "gluteus medius"], twoSided: true, equipment: null, photos: ["lean-back-90-90-hold-main.webp"],
    instructions: "1. Sit on the floor with your front leg bent in front of you to about 90 degrees and your back leg out to the side, also bent to about 90 degrees.\n2. Place your hands on the floor behind your hips, fingers pointing back or to the side.\n3. Lean your trunk back onto your hands, keeping your arms straight and your chest open.\n4. Let both knees settle toward the floor without forcing them.\n5. Hold the position, breathing slowly, feeling a mild stretch in the outer hip of the front leg and the front of the hip of the back leg.\n6. Hold for the planned time, then switch the legs and hold on the other side.\n\n• Use this version when the upright 90/90 is too intense; lean further back on your hands to ease the stretch.\n• Keep your shoulders down and away from your ears rather than hanging on your arms.\n• Move slowly into the position and keep it pain-free, especially at the knees." },
  { id: "legs-up-the-wall", name: "Legs-Up-the-Wall Pose", muscles: ["hamstrings", "erector spinae"], twoSided: false, equipment: null, photos: ["legs-up-the-wall-main.webp"],
    instructions: "1. Sit sideways next to a wall with one hip touching it.\n2. Swing the legs up the wall as you lie back, so the hips end close to the base of the wall.\n3. Let the legs rest against the wall with the feet relaxed and the arms open at the sides.\n4. Stay for the prescribed time, breathing slowly.\n5. Bend the knees and roll to one side to come out.\n\n• Slide the hips a few centimetres away from the wall if the hamstrings feel pulled.\n• Place a folded blanket under the pelvis for a gentler, more supported version.\n• Keep the legs passive; this position is meant to cost no effort." },
  { id: "lizard-stretch", name: "Lizard Stretch", muscles: ["adductors", "hip flexors", "gluteus maximus", "hamstrings"], twoSided: true, equipment: null, photos: ["lizard-stretch-main.webp"],
    instructions: "1. Step one foot forward into a deep lunge, foot placed wide.\n2. Lower both forearms toward the floor inside the front foot.\n3. Extend the back leg straight and let the hips sink.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Rest on your hands instead of forearms for an easier version.\n• Stretch to mild tension, never to pain." },
  { id: "low-lunge", name: "Low Lunge", muscles: ["hip flexors", "quadriceps", "erector spinae", "gluteus maximus"], twoSided: true, equipment: null, photos: ["low-lunge-main.webp"],
    instructions: "1. From kneeling, step one foot forward so the knee stacks over the ankle.\n2. Lower the back knee to the floor and untuck that foot.\n3. Tuck the tailbone slightly and press the hips forward until you feel the front of the back thigh lengthen.\n4. Lift the chest, raise the arms if it feels good, and hold for the prescribed time.\n5. Step back and repeat on the other side.\n\n• Pad the back knee with a folded mat if the floor is hard.\n• Squeeze the back glute to deepen the stretch without arching the lower back.\n• Keep the front knee above the ankle rather than letting it slide forward." },
  { id: "low-lunge-to-half-split", name: "Low Lunge to Half Split", muscles: ["hamstrings", "gastrocnemius", "hip flexors"], twoSided: true, equipment: null, photos: ["low-lunge-to-half-split-peak.webp", "low-lunge-to-half-split-start.webp"],
    instructions: "1. Start in a low lunge with the back knee on the floor and the front knee over the ankle.\n2. Press the hands into the floor or onto blocks either side of the front foot.\n3. Shift the hips back over the back knee and straighten the front leg, flexing that foot.\n4. Hold the half split briefly, then glide the hips forward into the low lunge again.\n5. Repeat for the desired number of repetitions and change sides.\n\n• Keep the back of the front leg long: bend the knee slightly rather than rounding the spine to reach.\n• Move the hips, not the front foot; the foot stays where it started.\n• Pad the back knee and use blocks under the hands if the floor is out of reach." },
  { id: "lying-quad-stretch", name: "Lying Quad Stretch", muscles: ["quadriceps", "hip flexors"], twoSided: true, equipment: null, photos: ["lying-quad-stretch-main.webp"],
    instructions: "1. Lie on your side with your legs straight and your head resting on your lower arm.\n2. Bend your top knee and take hold of that foot or ankle with your top hand.\n3. Gently pull your heel toward your glute, keeping your knees close together.\n4. Tuck your pelvis slightly so your lower back does not arch.\n5. Hold the stretch for the planned time while breathing slowly.\n6. Release the foot, roll to the other side and repeat.\n\n• Keep the knees side by side; letting the top knee drift forward turns it into a hip stretch.\n• Do not pull the heel hard; ease into a stretch you feel in the front of the thigh, not in the knee.\n• If you cannot reach the foot, loop a towel or strap around the ankle and pull on that." },
  { id: "pigeon-stretch", name: "Pigeon Stretch", muscles: ["gluteus maximus", "gluteus medius", "hip flexors"], twoSided: true, equipment: null, photos: ["pigeon-stretch-main.webp"],
    instructions: "1. From all fours, bring one knee forward and lay the shin across in front.\n2. Extend the other leg straight back, top of the foot down.\n3. Sink your hips toward the floor and keep them square.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Place a cushion under the hip if it does not reach the floor.\n• Walk your hands forward to deepen the stretch." },
  { id: "pyramid-pose", name: "Pyramid Pose", muscles: ["hamstrings", "erector spinae", "gastrocnemius"], twoSided: true, equipment: null, photos: ["pyramid-pose-main.webp"],
    instructions: "1. Step one foot back about a leg's length and turn the back foot out slightly.\n2. Square both hip points towards the front of the mat and keep both legs straight.\n3. Hinge from the hips and fold over the front leg, bringing the hands to the floor, blocks or the shin.\n4. Hold the fold for the prescribed time with the spine long rather than rounded.\n5. Press into the feet to come up and repeat on the other side.\n\n• Shorten the stance until both hips can face forward; length is worth less than square hips.\n• Use blocks under the hands so the chest can keep reaching towards the shin.\n• Micro-bend the front knee if the hamstring grips." },
  { id: "reclined-butterfly", name: "Reclined Butterfly", muscles: ["adductors", "gluteus maximus", "hip flexors"], twoSided: false, equipment: null, photos: ["reclined-butterfly-main.webp"],
    instructions: "1. Lie on your back with your knees bent and the soles of your feet flat on the floor.\n2. Bring the soles of your feet together and let both knees fall out to the sides.\n3. Rest your arms on the floor with your palms up, or place your hands on your belly.\n4. Keep your lower back resting on the floor and your shoulders relaxed.\n5. Breathe slowly and let your knees sink toward the floor for the planned time.\n6. Bring your knees together with your hands to finish.\n\n• Do not push the knees down with your hands; let gravity do the work so the inner thighs relax.\n• Slide your feet further from the hips to ease the stretch, or closer to deepen it.\n• Put a pillow or folded blanket under each knee if the stretch feels too strong." },
  { id: "seated-forward-fold", name: "Seated Forward Fold", muscles: ["hamstrings", "erector spinae"], twoSided: false, equipment: null, photos: ["seated-forward-fold-main.webp"],
    instructions: "1. Sit on the floor with both legs straight out in front.\n2. Keep your back long and hinge forward from the hips.\n3. Reach your hands toward your feet.\n4. Hold for 20 to 30 seconds, breathing steadily.\n\n• Lead with your chest, not your head, to keep the back long.\n• Stretch to mild tension, never to pain." },
  { id: "seated-straddle-stretch", name: "Seated Straddle Stretch", muscles: ["adductors", "hamstrings", "erector spinae"], twoSided: false, equipment: null, photos: ["seated-straddle-stretch-main.webp"],
    instructions: "1. Sit with your legs straight and spread wide in a V.\n2. Keep your back long and hinge forward from the hips.\n3. Walk your hands forward along the floor.\n4. Hold for 20 to 30 seconds, breathing steadily.\n\n• Keep your toes pointing up, not rolled in.\n• Ease into the stretch slowly — never bounce." },
  { id: "standing-adductor-stretch", name: "Standing Adductor Stretch", muscles: ["adductors", "hamstrings"], twoSided: true, equipment: null, photos: ["standing-adductor-stretch-main.webp"],
    instructions: "1. Stand with your feet about twice shoulder-width apart and your toes pointing forward.\n2. Put your hands on the bent knee or in front of you for support.\n3. Bend one knee and shift your hips sideways over that leg, keeping the other leg straight.\n4. Keep your chest up and both feet flat on the floor.\n5. Sink down until you feel a stretch along the inner thigh of the straight leg and hold it.\n6. Shift to the other side and repeat.\n\n• Keep the straight leg's foot flat or lift only the toes slightly; letting the foot roll out takes the stretch away.\n• Use your hands on the bent thigh to support your weight and keep your torso tall.\n• Do not bounce; sink slowly and stay within a stretch that feels strong but comfortable." },
  { id: "standing-forward-fold", name: "Standing Forward Fold", muscles: ["hamstrings", "erector spinae", "gastrocnemius"], twoSided: false, equipment: null, photos: ["standing-forward-fold-main.webp"],
    instructions: "1. Stand tall with your feet hip-width apart and legs straight.\n2. Hinge at your hips and fold your torso down toward the floor.\n3. Let your hands and head hang toward your feet.\n4. Hold for 20 to 30 seconds, breathing steadily.\n\n• Bend your knees slightly if your hamstrings feel tight.\n• Ease into the stretch slowly — never bounce." },
  { id: "standing-quad-stretch", name: "Standing Quad Stretch", muscles: ["quadriceps", "hip flexors"], twoSided: true, equipment: null, photos: ["standing-quad-stretch-main.webp"],
    instructions: "1. Stand on one leg, holding a wall for balance if needed.\n2. Bend the other knee and grab that ankle behind you.\n3. Pull the heel toward your glute, keeping knees together.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Tuck your pelvis under to deepen the stretch.\n• Keep your knees close together throughout." },
  { id: "standing-split", name: "Standing Split", muscles: ["gluteus maximus", "hamstrings", "erector spinae", "quadriceps"], twoSided: true, equipment: null, photos: ["standing-split-main.webp"],
    instructions: "1. From a forward fold, place both hands on the floor or on blocks beside the standing foot.\n2. Shift the weight onto one leg and lift the other leg behind you.\n3. Keep the standing leg straight and the hips as level as the lift allows.\n4. Hold the position for the prescribed time, drawing the chest towards the standing shin.\n5. Lower the lifted foot down and repeat on the other side.\n\n• Level the hips first and accept a lower lift; an open hip turns this into a different pose.\n• Use blocks under the hands so the spine can stay long.\n• Hold the standing ankle with one hand only when the balance is already steady." },
  { id: "triangle-pose", name: "Triangle Pose", muscles: ["hamstrings", "obliques", "adductors", "gluteus medius"], twoSided: true, equipment: null, photos: ["triangle-pose-main.webp"],
    instructions: "1. Stand wide with the front foot turned out and the back foot angled slightly in.\n2. Keep both legs straight and reach the front hand forward as the hips shift back.\n3. Tilt sideways and bring the bottom hand to the shin, a block or the floor, top arm reaching up.\n4. Hold the position for the prescribed time, turning the chest towards the ceiling.\n5. Press into the feet to come up and repeat on the other side.\n\n• Reach out over the front leg before you tilt down; folding early collapses the pose.\n• Use a block under the bottom hand rather than dragging the chest towards the floor.\n• Keep both legs straight and the kneecaps lifted." },
  { id: "wall-hamstring-stretch", name: "Wall Hamstring Stretch", muscles: ["hamstrings", "gastrocnemius"], twoSided: true, equipment: null, photos: ["wall-hamstring-stretch-main.webp"],
    instructions: "1. Lie on your back on the floor next to a wall or an open doorway, with your hips close to the wall.\n2. Raise one leg and rest the heel on the wall with the knee as straight as you can comfortably get it.\n3. Keep the other leg flat on the floor and your lower back relaxed.\n4. Shuffle your hips closer to the wall to increase the stretch, or move away to ease it.\n5. Breathe slowly and hold for the planned time while the hamstring relaxes.\n6. Lower the leg and repeat on the other side.\n\n• Keep your tailbone on the floor; lifting it off the floor takes the stretch out of the hamstring.\n• A slight bend in the knee is fine; straighten it only as far as feels comfortable.\n• Do not strain; the stretch should feel like a long pull, not sharp pain or tingling." },
  { id: "wide-legged-forward-fold", name: "Wide-Legged Forward Fold", muscles: ["adductors", "hamstrings", "erector spinae", "gastrocnemius"], twoSided: false, equipment: null, photos: ["wide-legged-forward-fold-main.webp"],
    instructions: "1. Stand with the feet wide apart and the outer edges parallel.\n2. Place the hands on the hips, lift the chest and hinge forward from the hip joints.\n3. Bring the hands to the floor under the shoulders and let the head hang.\n4. Hold the fold for the prescribed time, shifting the weight slightly into the balls of the feet.\n5. Bring the hands back to the hips and come up with a flat back.\n\n• Micro-bend the knees so the fold comes from the hips rather than the lower back.\n• Keep the feet parallel; turning them out takes the stretch out of the inner thighs.\n• Rest the hands on blocks when the floor is out of reach." },
  { id: "banded-adductor-stretch", name: "Banded Adductor Stretch", muscles: ["adductors", "hamstrings"], twoSided: true, equipment: "resistance band", photos: ["banded-adductor-stretch-main.webp"],
    instructions: "1. Lie on your back with a band looped around one foot.\n2. Raise that leg and let it open out to the side.\n3. Hold the band to control how far the leg lowers.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Keep your hips flat and both glutes on the floor.\n• Stretch to mild tension, never to pain." },
  { id: "banded-figure-4-stretch", name: "Banded Figure-4 Stretch", muscles: ["gluteus maximus", "gluteus medius"], twoSided: true, equipment: "resistance band", photos: ["banded-figure-4-stretch-main.webp"],
    instructions: "1. Lie on your back and cross one ankle over the opposite thigh.\n2. Loop a band around the supporting thigh.\n3. Pull both legs toward your chest with the band.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Keep your head and shoulders relaxed on the floor.\n• Let the crossed knee fall open." },
  { id: "banded-hamstring-stretch", name: "Banded Hamstring Stretch", muscles: ["hamstrings", "gastrocnemius"], twoSided: true, equipment: "resistance band", photos: ["banded-hamstring-stretch-main.webp"],
    instructions: "1. Lie on your back and loop a band around one foot.\n2. Raise that leg straight up, holding the band in both hands.\n3. Gently pull the band to draw the leg toward you.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Keep the raised leg as straight as you can.\n• Keep the other leg flat on the floor." },
  { id: "banded-it-band-stretch", name: "Banded IT-Band Stretch", muscles: ["abductors", "gluteus maximus", "gluteus medius"], twoSided: true, equipment: "resistance band", photos: ["banded-it-band-stretch-main.webp"],
    instructions: "1. Lie on your back with a band around one raised foot.\n2. Hold the band with the opposite hand.\n3. Draw the straight leg across your body toward the floor.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Keep both shoulders down on the floor.\n• Stop when you feel a stretch along the outer thigh." },
  { id: "bench-adductor-stretch", name: "Bench Adductor Stretch", muscles: ["adductors", "hamstrings"], twoSided: true, equipment: "flat bench", photos: ["bench-adductor-stretch-main.webp"],
    instructions: "1. Stand side-on to a bench.\n2. Rest one straight leg up on the bench out to the side.\n3. Keep your torso upright and shift gently toward the bench.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Keep both legs straight.\n• Keep the standing foot pointing forward." },
  { id: "bench-bulgarian-split-stretch", name: "Bench Bulgarian Split Stretch", muscles: ["hip flexors", "quadriceps", "gluteus maximus"], twoSided: true, equipment: "flat bench", photos: ["bench-bulgarian-split-stretch-main.webp"],
    instructions: "1. Rest the top of your rear foot on a bench behind you.\n2. Set the front foot flat and bend that knee.\n3. Sink your hips straight down.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Hold a wall for balance if needed.\n• Keep your torso upright." },
  { id: "bench-couch-stretch", name: "Bench Couch Stretch", muscles: ["hip flexors", "quadriceps"], twoSided: true, equipment: "flat bench", photos: ["bench-couch-stretch-main.webp"],
    instructions: "1. Kneel with your rear shin against the front of a bench.\n2. Place the front foot flat on the floor.\n3. Bring your torso upright until the front of the thigh stretches.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Squeeze the rear glute to protect your lower back.\n• Pad the rear knee on a cushion for comfort." },
  { id: "bench-figure-4-glute-stretch", name: "Bench Figure-4 Glute Stretch", muscles: ["gluteus maximus", "gluteus medius"], twoSided: true, equipment: "flat bench", photos: ["bench-figure-4-glute-stretch-main.webp"],
    instructions: "1. Sit on the end of a bench.\n2. Cross one ankle over the opposite knee.\n3. Keep your back flat and hinge forward over the crossed leg.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Let the crossed knee fall open.\n• Hinge from the hips, keeping the chest open." },
  { id: "bench-hamstring-stretch", name: "Bench Hamstring Stretch", muscles: ["hamstrings", "erector spinae"], twoSided: true, equipment: "flat bench", photos: ["bench-hamstring-stretch-main.webp"],
    instructions: "1. Place one heel on a bench with that leg straight.\n2. Stand tall on the supporting leg.\n3. Hinge forward from the hips over the raised leg.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Keep your back flat as you fold forward.\n• Keep the raised leg straight, toes up." },
  { id: "standing-calf-stretch", name: "Standing Calf Stretch", muscles: ["gastrocnemius", "soleus"], twoSided: true, equipment: null, photos: ["standing-calf-stretch-main.webp"],
    instructions: "1. Step one foot back into a staggered stance.\n2. Keep the back leg straight and the heel pressed down.\n3. Bend the front knee and lean your weight forward.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Keep the rear heel flat and toes pointing forward.\n• Bend the rear knee slightly to target the lower calf." },
  { id: "banded-ankle-stretch", name: "Banded Ankle Stretch", muscles: ["gastrocnemius", "soleus"], twoSided: true, equipment: "resistance band", photos: ["banded-ankle-stretch-main.webp"],
    instructions: "1. Sit with one leg extended and a band around the forefoot.\n2. Hold the band in both hands.\n3. Pull so the toes draw back toward your shin.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Keep the leg straight and relaxed.\n• Stretch to mild tension, never to pain." },
  { id: "banded-calf-stretch", name: "Banded Calf Stretch", muscles: ["gastrocnemius", "soleus"], twoSided: true, equipment: "resistance band", photos: ["banded-calf-stretch-main.webp"],
    instructions: "1. Lie on your back and loop a band around the ball of one foot.\n2. Raise the leg and keep it fairly straight.\n3. Pull the band so your toes draw back toward your shin.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Keep the pull steady, not jerky.\n• Keep the knee softly straight." },
  { id: "bench-ankle-stretch", name: "Bench Ankle Stretch", muscles: ["gastrocnemius", "soleus"], twoSided: true, equipment: "flat bench", photos: ["bench-ankle-stretch-main.webp"],
    instructions: "1. Place one whole foot flat on top of a bench.\n2. Keep your torso upright.\n3. Drive that knee forward over your toes.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Keep your heel down on the bench.\n• Move slowly and keep the foot flat." },
  { id: "bench-calf-stretch", name: "Bench Calf Stretch", muscles: ["gastrocnemius", "soleus"], twoSided: true, equipment: "flat bench", photos: ["bench-calf-stretch-main.webp"],
    instructions: "1. Place the ball of one foot on the edge of a bench.\n2. Keep that knee straight.\n3. Let your heel drop down below the toes.\n4. Hold for 20 to 30 seconds, breathing steadily.\n5. Switch sides and repeat.\n\n• Hold the bench or a wall for balance.\n• Keep the movement slow and controlled." },
  { id: "wrist-flexor-stretch", name: "Wrist Flexor Stretch", muscles: ["forearm flexors"], twoSided: true, equipment: null, photos: [],
    instructions: "Hold one arm straight out in front of you, palm up. With the other hand, gently pull the fingers down and back toward you until you feel a stretch along the inside of the forearm. Keep the elbow straight." },
  { id: "wrist-extensor-stretch", name: "Wrist Extensor Stretch", muscles: ["forearm extensors"], twoSided: true, equipment: null, photos: [],
    instructions: "Hold one arm straight out in front of you, palm down. Bend the wrist so the fingers point at the floor and gently press the back of the hand toward you with the other hand until you feel a stretch along the top of the forearm." },
  { id: "prayer-stretch", name: "Prayer Stretch", muscles: ["forearm flexors"], twoSided: false, equipment: null, photos: [],
    instructions: "Press your palms together in front of your chest, fingers pointing up. Keeping the palms together, slowly lower your hands toward your waist until you feel a stretch in the wrists and forearms." },
];

export function findLibraryStretch(id) {
  return STRETCH_LIBRARY.find(s => s.id === id) || null;
}

// Picture URLs of a library stretch, held position first.
export function libraryPhotoUrls(id) {
  return (findLibraryStretch(id)?.photos || []).map(file => `./climbing-tracker/stretches/${file}`);
}

// A new stretch exercise (without id) made from a library entry.
export function stretchExerciseFromLibrary(stretch) {
  return {
    name: stretch.name,
    type: "stretch",
    holdSec: DEFAULT_HOLD_SEC,
    twoSided: stretch.twoSided,
    notes: stretch.instructions,
    photo: { library: stretch.id },
  };
}

// Case-insensitive match on the name, a muscle or the equipment.
export function searchLibrary(query) {
  const q = query.trim().toLowerCase();
  if (!q) return STRETCH_LIBRARY;
  return STRETCH_LIBRARY.filter(s =>
    s.name.toLowerCase().includes(q) || s.muscles.some(m => m.includes(q)) || (s.equipment || "").includes(q));
}
